const MODES: [Rounding; 4] = [Rounding::Nearest, Rounding::Up, Rounding::Down, Rounding::Zero];

fn mp_round(m: Rounding) -> Round {
    match m {
        Rounding::Nearest => Round::Nearest,
        Rounding::Up => Round::Up,
        Rounding::Down => Round::Down,
        Rounding::Zero => Round::Zero,
    }
}

/// A deterministic generator (xorshift64*).
struct Rng(u64);
impl Rng {
    fn bits(&mut self) -> u64 {
        self.0 ^= self.0 >> 12;
        self.0 ^= self.0 << 25;
        self.0 ^= self.0 >> 27;
        self.0.wrapping_mul(0x2545_f491_4f6c_dd1d)
    }
    /// Operands of moderate magnitude (some subnormal, some huge) of format `fmt`.
    fn operand(&mut self, fmt: Fmt) -> u128 {
        let r = self.bits();
        let frac_bits = if fmt.explicit_lead { fmt.prec } else { fmt.prec - 1 };
        let frac = ((u128::from(self.bits()) << 64) | u128::from(self.bits())) & ((1u128 << (fmt.prec - 1)) - 1);
        let span = i64::from(fmt.emax) * 2;
        let e = match r % 8 {
            0 => 0,                                       // subnormal
            1 => (self.bits() % span as u64) as i64 + 1,   // anywhere
            _ => i64::from(fmt.emax) + (self.bits() % 41) as i64 - 20,
        };
        let lead = if fmt.explicit_lead && e != 0 { 1u128 << 63 } else { 0 };
        (u128::from(r & 1) << (frac_bits + fmt.exp_bits)) | ((e as u128) << frac_bits) | lead | frac
    }
}

/// Every format's correctly rounded `sqrt` and `fma` against the oracle, in every mode, flags
/// included.
fn cr_against_oracle<F: Float>(fmt: Fmt, n: usize) {
    let mut rng = Rng(0x5eed_0000 + u64::from(fmt.prec));
    for i in 0..n {
        let (xb, yb, zb) = (rng.operand(fmt), rng.operand(fmt), rng.operand(fmt));
        let (x, y, z) = (F::from_bits(xb), F::from_bits(yb), F::from_bits(zb));
        let (bx, by, bz) = (Big::from_bits(fmt, xb), Big::from_bits(fmt, yb), Big::from_bits(fmt, zb));
        let mode = MODES[i % 4];
        let (got, st) = fused::fma(x, y, z, mode);
        let (want, wf) = bx.mul(&by).add(&bz).round_to(fmt, mp_round(mode));
        if !Big::from_bits(fmt, want).is_nan() {
            assert_eq!(got.to_bits(), want, "fma {xb:x} {yb:x} {zb:x} {mode:?}");
            assert_eq!(st.flags.any(Flags::INEXACT), wf.inexact, "fma inexact {xb:x} {yb:x} {zb:x}");
            assert_eq!(st.flags.any(Flags::UNDERFLOW), wf.underflow, "fma underflow {xb:x} {yb:x} {zb:x} {mode:?}");
            assert_eq!(st.flags.any(Flags::OVERFLOW), wf.overflow, "fma overflow {xb:x} {yb:x} {zb:x}");
        }
        let ax = bx.abs();
        let (got, _) = fused::sqrt::<F, F>(fl::with_sign(x, false), mode);
        let want = mp::correctly_rounded(fmt, mp_round(mode), 1 << 12, |p| {
            let v = ax.sqrt(p, Round::Nearest);
            mp::Approx { exact: v.mul(&v).identical(&ax), value: v }
        });
        assert_eq!(got.to_bits(), want.unwrap().0, "sqrt {xb:x} {mode:?}");
    }
}

#[test]
fn s10_0_c_0() {
    // One generic implementation per operation: the same call in every format.
    fn check<F: Float>(two_and_half: F, three: F) {
        assert_eq!(round::ceil(two_and_half).0, three);
    }
    check(2.5f32, 3.0f32);
    check(2.5f64, 3.0f64);
    check(F80((0x4000u128 << 64) | (0xa0u128 << 56)), F80((0x4000u128 << 64) | (0xc0u128 << 56)));
    check(F128((0x4000u128 << 112) | (1u128 << 110)), F128((0x4000u128 << 112) | (1u128 << 111)));
}

