#[test]
fn s10_0_c_p1() {
    // The contract is the same in every format; only range and precision differ: the largest
    // finite value plus its half-ulp overflows in round-to-nearest everywhere.
    fn overflow<F: Float>() {
        let max = fl::max_finite::<F>(false);
        let (v, st) = manip::scale(max, 1, Rounding::Nearest);
        assert_eq!(v, fl::inf::<F>(false));
        assert_eq!(st, Status { flags: Flags(0x28), error: MathError::Range, hw: Status::HW_ANY });
    }
    overflow::<f32>();
    overflow::<f64>();
    overflow::<F80>();
    overflow::<F128>();
}

#[test]
fn s10_0_f_0() {
    // Domain error: EDOM and invalid.
    assert_eq!(fused::sqrt::<f64, f64>(-1.0, Rounding::Nearest).1, Status::DOMAIN);
    assert_eq!(rem::fmod(1.0f32, 0.0).1, Status::DOMAIN);
    // Range errors: ERANGE for an overflow to ∞ and an underflow to 0 only.
    assert_eq!(manip::scale(1.0f64, 2000, Rounding::Nearest).1.error, MathError::Range);
    assert_eq!(manip::scale(1.0f64, 2000, Rounding::Zero), (f64::MAX, Status::flags(Flags(0x28))));
    assert_eq!(manip::scale(1.0f64, -2000, Rounding::Nearest).1, Status { flags: Flags(0x30), error: MathError::Range, hw: Status::HW_ANY });
    assert_eq!(manip::scale(1.5f64, -1074, Rounding::Nearest).1, Status::flags(Flags(0x30)));
    // The functions that report through the flags only.
    assert_eq!(round::lrint(1e300f64, Rounding::Nearest).1, Status::INVALID);
    assert_eq!(round::lround(f64::NAN).1, Status::INVALID);
    assert_eq!(fused::fma(f64::INFINITY, 0.0, 1.0, Rounding::Nearest).1, Status::INVALID);
    assert_eq!(fused::fma(f64::MAX, 2.0, 0.0, Rounding::Nearest).1, Status::flags(Flags(0x28)));
    assert_eq!(rem::remquo(1.0f64, 0.0).1, Status::INVALID);
    assert_eq!(manip::logb(0.0f64).1, Status::flags(Flags::DIVBYZERO));
    assert_eq!(manip::nextafter(0.0f64, 1.0).1, Status::flags(Flags(0x30)));
    assert_eq!(manip::nextafter(5e-324f64, 1.0).1.error, MathError::Range);
}

#[test]
fn s10_0_g_0() {
    // Correctly rounded: sqrt and fma in every format and mode against the oracle; the
    // narrowing operations, fmod, remainder and rounding have their own clauses (§10.2, §10.4).
    cr_against_oracle::<f32>(Fmt::F32, 20_000);
    cr_against_oracle::<f64>(Fmt::F64, 20_000);
    cr_against_oracle::<F80>(Fmt::F80, 5_000);
    cr_against_oracle::<F128>(Fmt::F128, 5_000);
}

#[test]
fn s10_0_g2_0() {
    let qnan = f64::NAN;
    let snan = f64::from_bits(0x7ff4_0000_0000_0001);
    // A quiet NaN propagates without invalid; a signalling one raises it and is quieted.
    assert_eq!(fused::add::<f64, f64>(qnan, 1.0, Rounding::Nearest).1, Status::OK);
    let (v, st) = fused::add::<f64, f64>(snan, 1.0, Rounding::Nearest);
    assert_eq!((v.to_bits(), st), (0x7ffc_0000_0000_0001, Status::INVALID));
    assert_eq!(round::ceil(snan).1, Status::INVALID);
    // Infinities and signed zeros follow Annex F.
    assert_eq!(fused::sqrt::<f64, f64>(f64::INFINITY, Rounding::Nearest).0, f64::INFINITY);
    assert_eq!(fused::mul::<f64, f64>(-0.0, 5.0, Rounding::Nearest).0.to_bits(), 1 << 63);
    assert_eq!(rem::fmod(-0.0f64, 3.0).0.to_bits(), 1 << 63);
}

#[test]
fn s10_1_c_1() {
    assert_eq!(classify::fpclassify(f64::NAN), FP_NAN);
    assert_eq!(classify::fpclassify(f32::NEG_INFINITY), FP_INFINITE);
    assert_eq!(classify::fpclassify(-0.0f64), FP_ZERO);
    assert_eq!(classify::fpclassify(1e-310f64), FP_SUBNORMAL);
    assert_eq!(classify::fpclassify(F128(0x3fffu128 << 112)), FP_NORMAL);
    assert!(classify::signbit(-0.0f64) && classify::signbit(f64::from_bits(0xfff8_0000_0000_0000)));
    assert!(classify::is_signaling(f32::from_bits(0x7fa0_0000)) && !classify::is_signaling(f32::NAN));
    // x87: a pseudo-denormal is a non-canonical normal-range number; an unnormal is not a number.
    let pseudo = F80((1u128 << 63) | 1);
    assert!(!classify::is_canonical(pseudo) && classify::fpclassify(pseudo) == FP_NORMAL);
    assert_eq!(classify::fpclassify(F80(0x3fffu128 << 64)), FP_NAN);
    // Classification raises nothing, even for a signalling NaN (s10_math_symbols.rs checks the
    // exports against the hardware flags).
    assert!(classify::is_nan(f64::from_bits(0x7ff4_0000_0000_0000)));
}

#[test]
fn s10_1_c_2() {
    // The quiet comparisons (`isgreater`, ..., macros over these orders) raise nothing on a quiet
    // NaN: the internal order is total over non-NaN values and reports NaN as unordered.
    let (a, b) = (fl::decode(1.0f64), fl::decode(f64::NAN));
    assert_eq!(manip::compare(&a, &b), None);
    assert_eq!(manip::compare(&fl::decode(-0.0f64), &fl::decode(0.0f64)), Some(core::cmp::Ordering::Equal));
}

#[test]
fn s10_1_c_3() {
    assert_eq!(classify::iseqsig(1.0f64, 1.0), (true, Status::OK));
    assert_eq!(classify::iseqsig(-0.0f32, 0.0), (true, Status::OK));
    assert_eq!(classify::iseqsig(f64::NAN, 1.0), (false, Status::DOMAIN));
}

#[test]
fn s10_1_c_4() {
    let snan = f64::from_bits(0x7ff4_0000_0000_0001);
    assert!(classify::totalorder(-0.0f64, 0.0) && !classify::totalorder(0.0f64, -0.0));
    assert!(classify::totalorder(f64::INFINITY, snan) && classify::totalorder(snan, f64::NAN));
    assert!(classify::totalorder(f64::from_bits(0xfff8_0000_0000_0000), f64::NEG_INFINITY));
    assert!(classify::totalordermag(-1.0f64, 2.0) && !classify::totalordermag(-3.0f64, 2.0));
}

#[test]
fn s10_2_t_r1() {
    for (x, c, f, t, r, e) in [(2.5f64, 3.0, 2.0, 2.0, 3.0, 2.0), (-2.5, -2.0, -3.0, -2.0, -3.0, -2.0), (-0.5, -0.0, -1.0, -0.0, -1.0, -0.0)] {
        assert_eq!(round::ceil(x), (c, Status::OK));
        assert_eq!(round::floor(x), (f, Status::OK));
        assert_eq!(round::trunc(x), (t, Status::OK));
        assert_eq!(round::round(x), (r, Status::OK));
        assert_eq!(f64::to_bits(round::roundeven(x).0), f64::to_bits(e));
    }
}

